-- Independent BR-048 source controls. $1 inclusive, $2 exclusive start date.
-- FF-S01 source shape; FF-S02 selector/fallback evidence; FF-S03 target shape.
WITH e AS MATERIALIZED (
 SELECT r._idrref contract_ref,r._fld681rref client_ref,r._fld687rref club_ref,r._marked contract_marked,client._idrref joined_client_ref,club._idrref joined_club_ref
 FROM public._reference59 r JOIN public._reference141x1 client ON client._idrref=r._fld681rref LEFT JOIN public._reference132 club ON club._idrref=r._fld687rref
 WHERE r._fld671>=greatest($1::date,DATE '2024-01-01') AND r._fld671<$2::date AND r._fld671<r._fld672 AND r._fld671<CURRENT_DATE AND r._description::text NOT LIKE '%ИП%' AND r._description::text NOT LIKE '%сотруд%' AND client._code IS NOT NULL AND client._description IS NOT NULL AND r._fld681rref<>decode('00000000000000000000000000000000','hex') AND r._fld696rref<>decode('9b656ee141a764e44de79e83cd30c1b2','hex') AND r._fld693>6 AND r._fld694rref=ANY(ARRAY[decode('bc06e4b21430ebfb44a67a65c46d41f9','hex'),decode('9e369ac955bf602149e17b549b0f1498','hex'),decode('91e4594e35ce15d847c4a3f32e1e18f2','hex')]) AND r._fld670 IS NOT NULL AND client._fld1507 IS NOT NULL AND extract(epoch FROM(r._fld670-client._fld1507))/86400.0/365.0>=14
)
SELECT 'FF-S01'::text control_id,count(*)::bigint eligible_contract_rows,(count(*)-count(DISTINCT contract_ref))::bigint duplicate_contract_ref_rows,count(*) FILTER(WHERE contract_marked)::bigint marked_contract_rows,count(*) FILTER(WHERE joined_client_ref IS NULL)::bigint client_orphan_rows,count(*) FILTER(WHERE club_ref IS NULL OR joined_club_ref IS NULL)::bigint club_orphan_rows FROM e;

WITH e AS MATERIALIZED (
 SELECT r._idrref contract_ref,r._fld681rref client_ref,r._fld671::date start_date,r._fld687rref club_ref,r._fld694rref tenure_ref,r._fld674 purchase_at,r._fld693 term_value,r._fld670 activation_at
 FROM public._reference59 r JOIN public._reference141x1 client ON client._idrref=r._fld681rref
 WHERE r._fld671>=greatest($1::date,DATE '2024-01-01') AND r._fld671<$2::date AND r._fld671<r._fld672 AND r._fld671<CURRENT_DATE AND r._description::text NOT LIKE '%ИП%' AND r._description::text NOT LIKE '%сотруд%' AND client._code IS NOT NULL AND client._description IS NOT NULL AND r._fld681rref<>decode('00000000000000000000000000000000','hex') AND r._fld696rref<>decode('9b656ee141a764e44de79e83cd30c1b2','hex') AND r._fld693>6 AND r._fld694rref=ANY(ARRAY[decode('bc06e4b21430ebfb44a67a65c46d41f9','hex'),decode('9e369ac955bf602149e17b549b0f1498','hex'),decode('91e4594e35ce15d847c4a3f32e1e18f2','hex')]) AND r._fld670 IS NOT NULL AND client._fld1507 IS NOT NULL AND extract(epoch FROM(r._fld670-client._fld1507))/86400.0/365.0>=14
), ranked AS (SELECT *,row_number() OVER(PARTITION BY client_ref,start_date ORDER BY purchase_at DESC,term_value DESC,activation_at ASC,contract_ref ASC) n FROM e)
SELECT 'FF-S02'::text control_id,(SELECT count(*)::bigint FROM e) eligible_contract_rows,(SELECT count(*)::bigint FROM ranked WHERE n=1) selected_cohort_rows,(SELECT count(*)::bigint FROM e)- (SELECT count(*)::bigint FROM ranked WHERE n=1) collapsed_contract_rows,(SELECT count(*)::bigint FROM ranked WHERE n=1 AND (client_ref IS NULL OR start_date IS NULL OR club_ref IS NULL OR tenure_ref IS NULL)) invalid_selected_rows,(SELECT count(*)::bigint FROM (SELECT client_ref,start_date FROM ranked WHERE n=1 GROUP BY client_ref,start_date HAVING count(*)<>1) d) duplicate_selected_key_rows;

WITH e AS MATERIALIZED (
 SELECT r._idrref contract_ref,r._fld681rref client_ref,r._fld671::date start_date,r._fld687rref club_ref,CASE r._fld694rref WHEN decode('bc06e4b21430ebfb44a67a65c46d41f9','hex') THEN 'New' WHEN decode('9e369ac955bf602149e17b549b0f1498','hex') THEN 'Ex' WHEN decode('91e4594e35ce15d847c4a3f32e1e18f2','hex') THEN 'Renew' END::text tenure_type,r._fld674 purchase_at,r._fld693 term_value,r._fld670 activation_at
 FROM public._reference59 r JOIN public._reference141x1 client ON client._idrref=r._fld681rref
 WHERE r._fld671>=greatest($1::date,DATE '2024-01-01') AND r._fld671<$2::date AND r._fld671<r._fld672 AND r._fld671<CURRENT_DATE AND r._description::text NOT LIKE '%ИП%' AND r._description::text NOT LIKE '%сотруд%' AND client._code IS NOT NULL AND client._description IS NOT NULL AND r._fld681rref<>decode('00000000000000000000000000000000','hex') AND r._fld696rref<>decode('9b656ee141a764e44de79e83cd30c1b2','hex') AND r._fld693>6 AND r._fld694rref=ANY(ARRAY[decode('bc06e4b21430ebfb44a67a65c46d41f9','hex'),decode('9e369ac955bf602149e17b549b0f1498','hex'),decode('91e4594e35ce15d847c4a3f32e1e18f2','hex')]) AND r._fld670 IS NOT NULL AND client._fld1507 IS NOT NULL AND extract(epoch FROM(r._fld670-client._fld1507))/86400.0/365.0>=14
), ranked AS (SELECT *,row_number() OVER(PARTITION BY client_ref,start_date ORDER BY purchase_at DESC,term_value DESC,activation_at ASC,contract_ref ASC) n FROM e), t AS (SELECT * FROM ranked WHERE n=1)
SELECT 'FF-S03'::text control_id,count(*)::bigint target_candidate_rows,min(start_date) min_membership_start_date,max(start_date) max_membership_start_date,count(*) FILTER(WHERE client_ref IS NULL OR start_date IS NULL OR club_ref IS NULL OR tenure_type IS NULL)::bigint required_null_rows,count(*) FILTER(WHERE start_date>=CURRENT_DATE)::bigint future_start_rows,(count(*)-count(DISTINCT(client_ref,start_date)))::bigint duplicate_target_key_rows FROM t;
